edits.new:
denom <- hpx[j] - hpx[j + 1]
if (abs(denom) < 1e-12) {
  ## Equal tangent slopes => locally linear log-density (the tangent
  ## lines coincide); the split point is arbitrary, use the midpoint.
  z[j + 1] <- (x[j] + x[j + 1]) / 2
} else {
  z[j + 1] <- (hx[j + 1] - hx[j] - x[j + 1] * hpx[j + 1] +
               x[j] * hpx[j]) / denom
}

